    r0,r1=min(r for r,c in pts),max(r for r,c in pts)
    c0,c1=min(c for r,c in pts),max(c for r,c in pts)
    # Rays from the rectangular block extend along every colored row/column.
    # Dots of the marker color remain visible and are not overwritten.
    for r in range(r0, r1+1):
