    h,w=len(grid),len(grid[0]); out=[row[:] for row in grid]
    # The color-2 block acts as a stamp: each isolated marker is replaced
    # by the block's color at its own location only when inside its bounds.
    # Extend the colored block's occupied rows and columns across the canvas.
    pts=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==2]
    r0,r1=min(r for r,c in pts),max(r for r,c in pts); c0,c1=min(c for r,c in pts),max(c for r,c in pts)
    # Colored rectangle is projected along its diagonally corresponding marker directions.
    # Use the marker alignment: each marker chooses the nearest edge-aligned row/column.
    for r in range(r0,r1+1):
        for c in range(w):
            if grid[r][c]==0: out[r][c]=2
    for c in range(c0,c1+1):
        for r in range(h):
            if grid[r][c]==0: out[r][c]=2
    return out
